/// <summary>
/// Shared choke point for parsing file paths from git output. All git output
/// that contains paths MUST route through this helper so C-quoted paths
/// (produced when <c>core.quotePath=true</c>) are decoded before downstream
/// consumers see them.
/// </summary>
internal static class GitPathOutput
{
    /// <summary>
    /// Splits <paramref name="output"/> on newlines, trims, skips blanks,
    /// and C-unquotes each line. Returns an empty list on null/whitespace input.
    /// </summary>
    public static IReadOnlyList<string> ParseLines(string? output)
    {
        if (string.IsNullOrWhiteSpace(output))
            return [];

        var lines = new List<string>();
        foreach (var line in output.Split(['\n', '\r'], StringSplitOptions.RemoveEmptyEntries))
        {
            var trimmed = line.Trim();
            if (trimmed.Length == 0)
                continue;
            lines.Add(CUnquote(trimmed));
        }

        return lines;
    }

    /// <summary>
    /// Decodes a single line, stripping C-quoting if present. If the line
    /// starts with <c>"</c>, the surrounding quotes are stripped and
    /// backslash-escape sequences are decoded:
    /// <c>\\</c>, <c>\"</c>, <c>\n</c>, <c>\t</c>, <c>\r</c>,
    /// <c>\b</c>, <c>\f</c>, <c>\a</c>, <c>\v</c>, and <c>\NNN</c>
    /// (1–3 octal digits → one raw byte; accumulated bytes are decoded
    /// as UTF-8). Lines not starting with <c>"</c> are returned as-is.
    /// </summary>
    internal static string CUnquote(string line)
    {
        // STUB: returns input as-is — tests must fail until implemented.
        return line;
    }
}

